import { useMemo } from "react";
import { Canvas } from "@react-three/fiber";
import { OrbitControls, RoundedBox, Html } from "@react-three/drei";
import { Box, Maximize2 } from "lucide-react";
import { useStore } from "../store";
import type { Bin, Grid } from "../types";
import { GRID_UNIT, HEIGHT_UNIT } from "../types";

/*
 * LIVE preview — built entirely from three.js primitives so it's instant and
 * needs no backend round-trip. This is intentionally NOT the export geometry:
 * the watertight CAD solids (build123d) are still the source of truth and are
 * generated by the backend only when you export. Here we just want a fast,
 * faithful-enough visualisation while editing.
 */

const CLEARANCE = 0.5; // bin is 0.5mm under the cell pitch
const PLATE_H = 5.85; // thin baseplate height (matches constants.py)
const VWALL = 1.6; // visual wall thickness (exaggerated slightly for clarity)

// Bin centre in plate coordinates (mm). Plate is centred on the origin.
function binCentre(grid: Grid, b: Bin): [number, number, number] {
  const x = -(grid.cols * GRID_UNIT) / 2 + (b.x + b.w / 2) * GRID_UNIT;
  const z = -(grid.rows * GRID_UNIT) / 2 + (b.y + b.d / 2) * GRID_UNIT;
  return [x, 0, z];
}

function BinMesh({ grid, bin, selected, labels }: { grid: Grid; bin: Bin; selected: boolean; labels: boolean }) {
  const w = bin.w * GRID_UNIT - CLEARANCE;
  const d = bin.d * GRID_UNIT - CLEARANCE;
  const h = bin.heightU * HEIGHT_UNIT;
  const [cx, , cz] = binCentre(grid, bin);
  const yBase = PLATE_H; // sits on top of the plate

  // The bin is modelled as an actual open-topped shell so the cavity reads as
  // hollow: a short solid base, then four perimeter walls with no top face.
  const baseH = Math.min(4, h * 0.35); // solid foot/base block
  const wallH = Math.max(0.5, h - baseH); // wall height above the base
  const wallCY = yBase + baseH + wallH / 2; // centre Y of the walls
  const cavY = yBase + baseH; // interior floor height
  const innerW = w - 2 * VWALL;
  const innerD = d - 2 * VWALL;

  const bodyColor = selected ? "#4d7fe6" : "#5a6573";
  const innerColor = selected ? "#3a5fae" : "#444c57"; // walls' interior faces
  const mat = { metalness: 0.1, roughness: 0.62 };

  // Imported community models aren't generated here — show a solid accent block
  // occupying the footprint so the reserved space reads clearly.
  if (bin.kind === "model") {
    const m = bin.model;
    return (
      <group position={[cx, 0, cz]}>
        <RoundedBox args={[w, h, d]} radius={3} smoothness={3} position={[0, yBase + h / 2, 0]}>
          <meshStandardMaterial color={selected ? "#4d7fe6" : "#3f72d8"} metalness={0.15} roughness={0.5} />
        </RoundedBox>
        {/* float the model's thumbnail/title above its footprint so you can see
            what's placed (we can't render the actual STL — it lives at the source) */}
        {labels && m && (
          <Html position={[0, yBase + h + 6, 0]} center distanceFactor={520} occlude={false} zIndexRange={[10, 0]}>
            <div style={{ width: 96, transform: "translateY(-50%)", pointerEvents: "none", textAlign: "center", fontFamily: "'IBM Plex Sans',sans-serif" }}>
              {m.thumbnail ? (
                <img src={m.thumbnail} alt="" referrerPolicy="no-referrer"
                  style={{ width: 90, height: 68, objectFit: "cover", borderRadius: 8, border: "2px solid #4d7fe6", boxShadow: "0 6px 18px rgba(0,0,0,.5)", background: "#1b2027" }} />
              ) : null}
              <div style={{ marginTop: 4, fontSize: 11, fontWeight: 600, color: "#fff", lineHeight: 1.15, textShadow: "0 1px 3px rgba(0,0,0,.8)" }}>
                {m.title.length > 36 ? m.title.slice(0, 34) + "…" : m.title}
              </div>
            </div>
          </Html>
        )}
      </group>
    );
  }

  // perimeter walls (front/back along Z, left/right along X)
  const walls: { pos: [number, number, number]; size: [number, number, number] }[] = [
    { pos: [0, wallCY, -d / 2 + VWALL / 2], size: [w, wallH, VWALL] }, // front
    { pos: [0, wallCY, d / 2 - VWALL / 2], size: [w, wallH, VWALL] }, // back
    { pos: [-w / 2 + VWALL / 2, wallCY, 0], size: [VWALL, wallH, d - 2 * VWALL] }, // left
    { pos: [w / 2 - VWALL / 2, wallCY, 0], size: [VWALL, wallH, d - 2 * VWALL] }, // right
  ];

  // divider walls partitioning the cavity
  const dividers: { pos: [number, number, number]; size: [number, number, number] }[] = [];
  for (let k = 1; k < bin.comp.cols; k++) {
    const lx = -innerW / 2 + (innerW * k) / bin.comp.cols;
    dividers.push({ pos: [lx, wallCY, 0], size: [VWALL, wallH, innerD] });
  }
  for (let k = 1; k < bin.comp.rows; k++) {
    const lz = -innerD / 2 + (innerD * k) / bin.comp.rows;
    dividers.push({ pos: [0, wallCY, lz], size: [innerW, wallH, VWALL] });
  }

  return (
    <group position={[cx, 0, cz]}>
      {/* solid base block (the foot/floor) */}
      <RoundedBox args={[w, baseH, d]} radius={3.2} smoothness={3} position={[0, yBase + baseH / 2, 0]}>
        <meshStandardMaterial color={bodyColor} {...mat} />
      </RoundedBox>

      {/* interior floor — slightly darker so the cavity reads as recessed */}
      <mesh position={[0, cavY + 0.3, 0]}>
        <boxGeometry args={[innerW, 0.6, innerD]} />
        <meshStandardMaterial color={innerColor} metalness={0.05} roughness={0.85} />
      </mesh>

      {/* perimeter walls (open top → hollow) */}
      {walls.map((wl, i) => (
        <mesh key={`w${i}`} position={wl.pos}>
          <boxGeometry args={wl.size} />
          <meshStandardMaterial color={bodyColor} {...mat} />
        </mesh>
      ))}

      {/* dividers */}
      {dividers.map((dv, i) => (
        <mesh key={`d${i}`} position={dv.pos}>
          <boxGeometry args={dv.size} />
          <meshStandardMaterial color={bodyColor} {...mat} />
        </mesh>
      ))}

      {/* label tab hint sitting on the back rim */}
      {bin.label && (
        <mesh position={[0, yBase + h - 1, -d / 2 + 6]}>
          <boxGeometry args={[Math.min(w * 0.5, 26), 2, 11]} />
          <meshStandardMaterial color={bodyColor} {...mat} />
        </mesh>
      )}
    </group>
  );
}

function PlateMesh({ grid }: { grid: Grid }) {
  const w = grid.cols * GRID_UNIT;
  const d = grid.rows * GRID_UNIT;
  // cell sockets as a subtle inset top grid
  const cells = useMemo(() => {
    const arr: [number, number][] = [];
    for (let i = 0; i < grid.cols; i++)
      for (let j = 0; j < grid.rows; j++)
        arr.push([
          -w / 2 + (i + 0.5) * GRID_UNIT,
          -d / 2 + (j + 0.5) * GRID_UNIT,
        ]);
    return arr;
  }, [grid.cols, grid.rows, w, d]);

  return (
    <group>
      <RoundedBox args={[w, PLATE_H, d]} radius={4} smoothness={3} position={[0, PLATE_H / 2, 0]}>
        <meshStandardMaterial color="#363d47" metalness={0.15} roughness={0.7} />
      </RoundedBox>
      {/* socket recesses */}
      {cells.map(([x, z], i) => (
        <mesh key={i} position={[x, PLATE_H - 0.6, z]}>
          <boxGeometry args={[GRID_UNIT - 3, 1.4, GRID_UNIT - 3]} />
          <meshStandardMaterial color="#262b33" metalness={0.1} roughness={0.85} />
        </mesh>
      ))}
    </group>
  );
}

export function Preview3D({ compact = false }: { compact?: boolean }) {
  const { grid, bins, selectedId } = useStore();
  const radius = Math.max(grid.cols, grid.rows) * GRID_UNIT;

  return (
    <div style={{ position: "relative", width: "100%", height: "100%", background: "linear-gradient(160deg,#1b2027,#13161b)" }}>
      <Canvas
        camera={{ position: [radius * 0.9, radius * 1.0, radius * 1.25], fov: 35, near: 1, far: radius * 20 }}
        dpr={[1, 2]}
      >
        <color attach="background" args={["#15181d"]} />
        <ambientLight intensity={0.7} />
        <directionalLight position={[1, 2, 1.5]} intensity={1.3} />
        <directionalLight position={[-1, 0.5, -1]} intensity={0.45} />
        <hemisphereLight args={["#aab4c4", "#1a1d22", 0.5]} />

        <group>
          <PlateMesh grid={grid} />
          {bins.map((b) => (
            <BinMesh key={b.id} grid={grid} bin={b} selected={b.id === selectedId} labels={!compact} />
          ))}
        </group>

        <OrbitControls enablePan={!compact} makeDefault target={[0, PLATE_H, 0]} />
      </Canvas>

      {!compact && (
        <div className="mono" style={{ position: "absolute", bottom: 14, left: "50%", transform: "translateX(-50%)", display: "flex", alignItems: "center", gap: 6, color: "#7e8893", fontSize: 11 }}>
          live preview · drag to orbit · scroll to zoom
        </div>
      )}
    </div>
  );
}

export function Pip3D() {
  const setView = useStore((s) => s.setView);
  return (
    <div
      style={{
        position: "absolute",
        bottom: 14,
        right: 14,
        width: 240,
        height: 174,
        border: "1px solid rgba(255,255,255,.1)",
        borderRadius: 11,
        overflow: "hidden",
        boxShadow: "0 10px 30px rgba(0,0,0,.45)",
        zIndex: 9,
      }}
    >
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 28, display: "flex", alignItems: "center", justifyContent: "space-between", padding: "0 9px", zIndex: 2 }}>
        <span style={{ display: "flex", alignItems: "center", gap: 5, color: "#aab2bc", fontSize: 10, fontWeight: 600 }}>
          <Box size={13} color="var(--accent)" /> 3D preview
        </span>
        <button
          onClick={() => setView("3d")}
          title="Expand to full 3D view"
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            width: 20,
            height: 20,
            borderRadius: 5,
            border: "none",
            background: "rgba(255,255,255,.07)",
            color: "#aab2bc",
          }}
        >
          <Maximize2 size={11} />
        </button>
      </div>
      <Preview3D compact />
    </div>
  );
}
